/* UR5e extension. Legacy G1 pages and their demo data remain available. */
let pMode='demo', pLive=false, pStatus={}, pRows=[], pJobs=[], pBusy=false, pDemoCapture=null;
let pConfig;try{pConfig=JSON.parse(localStorage.getItem('embodied-hardware-v2'))}catch{};
pConfig=pConfig||{robotIp:'',serial:'',port:'',address:1,baud:921600};
let pDemoRows=[{id:'demo-pickplace',name:'UR5e · 抓取与放置示教',n_steps:1280,n_episodes:12,valid:true,
  arrays:{camera_0:{shape:[1280,480,640,3]},camera_1:{shape:[1280,480,640,3]},camera_2:{shape:[1280,480,640,3]},robot_joint:{shape:[1280,7]},action:{shape:[1280,7]},tactile:{shape:[1280,231]},tactile_resultant:{shape:[1280,3]}},errors:[],warnings:['演示数据：未进行实际采集。']},
  {id:'repo-sample',name:'仓库历史样例 · 元数据检查',n_steps:897,n_episodes:5,valid:false,arrays:{action:{shape:[897,7]},agent_pos:{shape:[896,7]},image0:{shape:[896,480,640,3]},image1:{shape:[896,480,640,3]}},errors:['action=897 帧，图像/状态=896 帧。','缺少原始时间戳，不能自动推断应删除哪一行。'],warnings:['检查结果来自已审计的仓库样例；此页面不是对本地数据的重新检测。']}];
const pLabels=[['ur5e','UR5e 工作台'],['sensors','RGB / 触觉接入'],['edge-data','实机数据管理'],['edge-train','DP 训练中心']];
pLabels.forEach(x=>pages.push(x));
$('#nav').insertAdjacentHTML('afterbegin','<div class="nav-label">UR5e · MULTIMODAL</div>'+pLabels.map(([id,n],i)=>`<a href="#${id}" data-page="${id}"><svg viewBox="0 0 24 24"><path d="${icons[i+1]}"/></svg>${n}</a>`).join('')+'<div class="nav-label">G1 · 演示项目</div>');
document.querySelector('.workspace strong').textContent='多设备 · 具身研发空间';
document.querySelector('.side-bottom small').textContent='G1 / UR5e / PaXini / RGB';
document.title='具身工坊 · 多模态研发平台';
const pModeTag=()=>badge(pMode==='demo'?'演示 · 非设备数据':'本地实机服务',pMode==='demo'?'amber':'');
const pHead=(name,desc,actions='')=>head(name,desc,`<button onclick="pSwitchMode()">${pMode==='demo'?'连接本地工作台':'切换演示'}</button>${actions}`)+`<div class="source-strip">${pModeTag()}<span>${pMode==='demo'?'在线展示可体验流程。采集与训练在本地工作台运行。':'设备状态来自本机服务；未连接的设备保持离线。'}</span><a href="downloads/edge-integration.zip" download>下载本地接入包 ↓</a></div>`;
async function pApi(path,body){const res=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(20000)});let value;try{value=await res.json()}catch{throw Error('本地服务未运行，请使用接入包启动本地工作台。')}if(!res.ok)throw Error(value.error||'请求失败');return value;}
function pSetup(){modal(`<div class="page-head"><h2>打开本地实机工作台</h2><button onclick="closeModal()" aria-label="关闭">✕</button></div><p>在线平台和本地平台使用同一套界面。硬件数据及训练任务留在实验室电脑。</p><ol><li>下载并解压本地接入包。</li><li>按包内 EDGE_SETUP.md 安装依赖。</li><li>启动：<code>python -m edge_agent.server</code></li><li>打开下方本地地址，再点击“连接本地工作台”。</li></ol><div class="warning">GELLO 已占用 RealSense 时，使用 GELLO 数据推送，不要再次独立打开同一相机。</div><div class="actions"><a href="downloads/edge-integration.zip" download><button class="primary">下载接入包</button></a><a href="http://127.0.0.1:8787/#ur5e" target="_blank" rel="noopener"><button>打开本地平台 ↗</button></a></div>`)}
async function pSwitchMode(){if(pMode==='live'){pMode='demo';pLive=false;render();return}try{const h=await pApi('health');if(h.service!=='embodied-edge')throw Error('服务不匹配');pMode='live';pLive=true;await pPoll();await pLoadData();render();toast('已连接本地服务；设备仍需分别接入')}catch(e){pSetup()}}
function pArm(){return `<svg viewBox="0 0 500 280" role="img" aria-label="UR5e 机械臂概念示意"><defs><pattern id="urgrid" width="28" height="28" patternUnits="userSpaceOnUse"><path d="M28 0H0V28" fill="none" stroke="#9fdfc1" stroke-width=".4"/></pattern></defs><rect width="500" height="280" fill="url(#urgrid)" opacity=".2"/><ellipse cx="218" cy="250" rx="125" ry="19" fill="#78ba9f22"/><g stroke="#b8d0cd" stroke-width="27" fill="none" stroke-linecap="round"><path d="M159 231v-70l75-82 88 56 13 46"/></g><g fill="#8bbad2" stroke="#496e7a" stroke-width="3"><circle cx="159" cy="164" r="23"/><circle cx="234" cy="79" r="23"/><circle cx="322" cy="136" r="19"/><circle cx="159" cy="229" r="25"/></g><path d="M335 184v21m-14-1h28m-28 0v15m28-15v15" stroke="#cae7d9" stroke-width="7" fill="none"/><rect x="114" y="249" width="90" height="10" rx="4" fill="#a7c4b9"/><path d="M315 204h75l22-20h44" stroke="#7fba9e" fill="none"/><text x="363" y="176" fill="#b9decc" font-size="10" font-family="monospace">PaXini M3025</text><text x="35" y="54" fill="#a0c9b9" font-size="10" font-family="monospace">UR5e / GELLO / DP</text><text x="35" y="70" fill="#6f9b8d" font-size="9">概念示意 · 非实时姿态</text></svg>`}
function pDeviceState(id){if(pMode==='demo')return badge('演示','amber');if(!pLive)return badge('服务离线','gray');const d=pStatus.devices?.[id];return badge(({streaming:'数据有效',stale:'数据过期',connecting:'连接中',error:'连接失败',disconnected:'未连接'})[d?.status]||'未连接',d?.status==='streaming'?'':'gray')}
function pOverview(){const rows=pMode==='demo'?pDemoRows:pRows;return pHead('UR5e · 多模态研发工作台','GELLO 示教，融合视觉与触觉，验证抓取与放置。',`<button class="primary" onclick="location.hash='sensors'">配置设备 →</button>`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">PHYSICAL LEARNING / UR5e WORKSPACE</div><h2>看见物体<br>感知接触，学习操作</h2><p>UR5e × RealSense RGB × PaXini M3025<br>7 维关节／夹爪动作 · Diffusion Policy</p><button onclick="location.hash='edge-data'">进入数据工作台 →</button></div><div class="robot-stage">${pArm()}</div></section><div class="metrics">${[['机械臂','UR5e','GELLO / RTDE'],['视觉','RGB','RealSense · 640 × 480'],['触觉','77','M3025 · 三轴测点'],['学习策略','DP','RGB 或 RGB＋触觉']].map(([a,b,c])=>`<div class="metric"><div class="metric-label">${a}</div><div class="metric-value">${b}</div><div class="subtle">${c}</div></div>`).join('')}</div><div class="grid2"><section class="card"><div class="card-head"><h2>接入状态</h2><a href="#sensors">管理设备 ↗</a></div><div id="p-device-summary">${pDeviceSummary()}</div></section><section class="card"><h2>从示教到模型</h2><div class="pipeline-list">${[['01','连接设备','UR5e、RGB 与串口触觉'],['02','采集并检查','GELLO 指令＋观测＋触觉对齐'],['03','选择 DP 模态','RGB 基线 / RGB＋触觉'],['04','训练与验证','离线损失、日志和模型检查点']].map(([i,a,b])=>`<div class="node-row"><span class="node-icon">${i}</span><div><strong>${a}</strong><small>${b}</small></div></div>`).join('')}</div></section></div><section class="card"><div class="card-head"><h2>数据入口检查</h2><a href="#edge-data">查看数据 →</a></div><p>训练前检查帧数、动作维度、片段边界和物理数据块。旧样例 897/896 帧错位会被明确拦截。</p><div class="actions" style="margin-top:15px">${badge(rows.filter(d=>d.valid).length+' 个结构有效')}${badge(rows.filter(d=>!d.valid).length+' 个待处理','amber')}<button onclick="location.hash='edge-train'">进入 DP 训练</button></div></section>`}
function pDeviceSummary(){return [['robot','UR5e 机械臂','只读关节／速度／TCP 状态'],['rgb','RealSense RGB','原始图像采集与预览'],['tactile','PaXini CP-M3025-Core','77 × 3 轴 / 串口 GEN3 UART'],['gello','GELLO 数采通道','PNG 图像＋关节反馈＋7D 指令']].map(([id,n,d])=>`<div class="node-row"><span class="node-icon">${id==='tactile'?'触':id==='rgb'?'视':'臂'}</span><div><strong>${n}</strong><small>${d}</small></div>${pDeviceState(id)}</div>`).join('')}
function pHeatmap(){const frame=pStatus.devices?.tactile?.sample;const points=pMode==='demo'?Array.from({length:77},(_,i)=>[Math.round(Math.sin(i)*4),Math.round(Math.cos(i)*3),Math.round(75*Math.exp(-((i%11-5)**2+(Math.floor(i/11)-3)**2)/8))]):frame?.points; if(!points)return '<div class="sensor-empty">尚未收到通过 LRC 校验的触觉帧</div>';return `<div class="taxels">${points.map((v,i)=>`<span title="点 ${i+1} · Fx ${v[0]} / Fy ${v[1]} / Fz ${v[2]} counts" style="background:rgba(10,141,110,${.08+Math.min(v[2]/128,.9)})">${v[2]}</span>`).join('')}</div><p class="subtle">77 个点按索引排列，非物理坐标布局。颜色＝Fz 原始计数。</p><div class="force-row">${['Fx','Fy','Fz'].map((k,i)=>`<div><small>${k} 合力</small><strong>${pMode==='demo'?[.3,-.2,2.6][i]:(frame.resultant_n[i]).toFixed(2)} <em>N</em></strong></div>`).join('')}</div>`}
function pRgb(){const sample=pStatus.devices?.rgb?.sample;return pMode==='demo'?`<div class="preview"><div class="preview-caption">RGB 示意 · 非相机画面</div>${pArm()}</div>`:sample?.image?`<img class="rgb-preview" alt="RealSense 实时 RGB" src="${sample.image}"><p class="subtle">采集时间 ${new Date(sample.timestamp*1000).toLocaleTimeString()} · 设备 ${esc(sample.camera_id||'RealSense')}</p>`:'<div class="sensor-empty">等待 RealSense / GELLO 图像帧</div>'}
function pRobotReadings(){const s=pStatus.devices?.robot?.sample||pStatus.devices?.gello?.sample;const joints=pMode==='demo'?[1.24,-1.46,1.38,-1.52,-1.65,-.35]:s?.joints?.slice(0,6);return `<div class="joint-readings">${Array.from({length:6},(_,i)=>`<div><small>J${i+1}</small><strong>${joints?Number(joints[i]).toFixed(3):'—'}</strong><small>rad</small></div>`).join('')}</div><p class="subtle">只读状态接入；该平台不会下发机械臂运动指令。</p>`}
views.ur5e=pOverview;
views.sensors=()=>pHead('RGB / 触觉 / 机械臂接入','配置实际设备，查看流状态、协议校验与采集质量。')+`<div class="grid-equal"><section class="card fields"><div class="card-head"><h2>UR5e 机械臂</h2><span id="p-robot-badge">${pDeviceState('robot')}</span></div><label for="p-ip">控制器 IP（只读 RTDE）</label><input id="p-ip" placeholder="填写现场机器人 IP" value="${esc(pConfig.robotIp)}"><div class="actions"><button class="primary" onclick="pConnect('robot')">连接状态流</button><button onclick="pDisconnect('robot')">断开</button></div><div id="p-robot-values">${pRobotReadings()}</div></section><section class="card fields"><div class="card-head"><h2>RealSense RGB</h2><span id="p-rgb-badge">${pDeviceState('rgb')}</span></div><label for="p-serial">相机序列号（独立预览）</label><input id="p-serial" placeholder="序列号，空值选择默认相机" value="${esc(pConfig.serial)}"><div class="actions"><button onclick="pDiscover('cameras')">发现相机</button><button class="primary" onclick="pConnect('rgb')">独立连接</button><button onclick="pDisconnect('rgb')">断开</button></div><p class="subtle">已有 GELLO 相机服务时使用下方数据推送，不重复打开相机。</p></section><section class="card fields"><div class="card-head"><h2>PaXini M3025 · GEN3</h2><span id="p-tactile-badge">${pDeviceState('tactile')}</span></div><div class="grid-equal"><div><label for="p-port">串口</label><input id="p-port" value="${esc(pConfig.port)}" placeholder="COM3 / /dev/ttyUSB0"></div><div><label for="p-address">设备地址（模块号＋1）</label><input id="p-address" type="number" min="1" max="255" value="${pConfig.address}"></div></div><label for="p-baud">波特率</label><input id="p-baud" type="number" value="${pConfig.baud}"><div class="actions"><button onclick="pDiscover('ports')">扫描串口</button><button class="primary" onclick="pConnect('tactile')">连接并读取</button><button onclick="pDisconnect('tactile')">断开</button></div><p class="subtle">手册 V1.0.5：921600 / 8N1 · 请求响应 · LRC 校验。只读，不自动校准。</p></section><section class="card"><h2>GELLO 多模态数采</h2><p>使用接入包内已集成的 GELLO 代码，并在启动现有采集命令前设置：</p><div class="log"># Linux\nexport EMBODIED_EDGE_URL=http://127.0.0.1:8787\n# PowerShell\n$env:EMBODIED_EDGE_URL='http://127.0.0.1:8787'</div><p class="subtle">平台接收 PNG 原图、反馈和目标指令；不会替你启动会移动机械臂的遥操作程序。</p><button onclick="pSetup()">接入说明 / 下载</button></section><section class="card"><div class="card-head"><h2>RGB 画面</h2>${pModeTag()}</div><div id="p-rgb-live">${pRgb()}</div></section><section class="card"><div class="card-head"><h2>触觉测点与合力</h2>${pModeTag()}</div><div id="p-touch-live">${pHeatmap()}</div></section><section class="card wide"><div class="card-head"><h2>连接诊断</h2><button onclick="pPoll(true)">刷新状态</button></div><div id="p-device-errors">${pDiagnostics()}</div></section></div>`;
function pDiagnostics(){if(pMode==='demo')return '<p>当前为演示模式。设备配置仅保存在本浏览器，点击连接不会产生实际设备访问。</p>';return Object.entries(pStatus.devices||{}).map(([k,v])=>`<p><strong>${esc(k)}</strong> · ${esc(v.status)} ${v.error?'<span class="danger">'+esc(v.error)+'</span>':''}</p>`).join('')||'<p>等待本地服务状态。</p>'}
function pSaveConfig(){for(const [field,key] of [['p-ip','robotIp'],['p-serial','serial'],['p-port','port'],['p-address','address'],['p-baud','baud']])if($('#'+field))pConfig[key]=$('#'+field).value;localStorage.setItem('embodied-hardware-v2',JSON.stringify(pConfig))}
async function pConnect(device){pSaveConfig();if(pMode==='demo')return toast('配置已保存。实际连接请使用本地工作台。');const config=device==='robot'?{ip:pConfig.robotIp}:device==='rgb'?{serial:pConfig.serial}:{port:pConfig.port,device_id:Number(pConfig.address),baudrate:Number(pConfig.baud)};try{await pApi('devices/connect',{device,config});toast('连接请求已提交，状态以有效数据帧为准');await pPoll()}catch(e){toast(e.message)}}
async function pDisconnect(device){if(pMode==='demo')return toast('演示模式没有实际设备连接');try{await pApi('devices/disconnect',{device});await pPoll()}catch(e){toast(e.message)}}
async function pDiscover(kind){if(pMode==='demo')return pSetup();try{const r=await pApi(kind);modal(`<div class="page-head"><h2>${kind==='ports'?'串口列表':'RealSense 设备'}</h2><button onclick="closeModal()">✕</button></div><pre class="log">${esc(JSON.stringify(r,null,2))}</pre><p>将对应串口或序列号填入设备配置。</p>`)}catch(e){toast(e.message)}}
async function pPoll(show=false){if(pMode!=='live')return;if(pBusy)return;pBusy=true;try{pStatus=await pApi('status');pLive=true;for(const k of ['robot','rgb','tactile']){const b=$('#p-'+k+'-badge');if(b)b.innerHTML=pDeviceState(k)}if($('#p-device-summary'))$('#p-device-summary').innerHTML=pDeviceSummary();if($('#p-rgb-live'))$('#p-rgb-live').innerHTML=pRgb();if($('#p-touch-live'))$('#p-touch-live').innerHTML=pHeatmap();if($('#p-robot-values'))$('#p-robot-values').innerHTML=pRobotReadings();if($('#p-device-errors'))$('#p-device-errors').innerHTML=pDiagnostics();if($('#p-capture-status'))$('#p-capture-status').textContent=pStatus.capture?.active?`已记录 ${pStatus.capture.frame_count} 帧 ${pStatus.capture.error||''}`:'未采集';if($('#p-jobs'))$('#p-jobs').innerHTML=pJobsTable();if(show)toast('已刷新本地状态')}catch(e){pLive=false;if($('#p-device-errors'))$('#p-device-errors').textContent='本地服务连接中断：'+e.message; if(show)toast(e.message)}finally{pBusy=false}}
async function pLoadData(){if(pMode==='demo'){pRows=pDemoRows;return}pRows=await pApi('datasets')}
function pDataTable(){const rows=pMode==='demo'?pDemoRows:pRows;return `<div class="table-wrap"><table><thead><tr><th>选择</th><th>数据集 / 来源</th><th>片段 / 帧</th><th>模态</th><th>检查结果</th><th>操作</th></tr></thead><tbody>${rows.map((d,i)=>`<tr><td><input type="checkbox" class="p-combine" value="${i}" aria-label="选择数据集 ${i+1}"></td><td><strong>${esc(d.name)}</strong><small>${pMode==='demo'?'演示 / 样例审计':'本地设备采集'} · ${esc(d.id)}</small></td><td>${d.n_episodes||'—'} / ${d.n_steps||'—'}</td><td>${d.arrays?.tactile?'RGB＋触觉':'RGB＋状态'}</td><td>${badge(d.valid?'结构有效':'需处理',d.valid?'':'amber')}</td><td><button onclick="pAudit(${i})">详细检查</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无本地数据。通过 GELLO 推送并保存片段，或把现有 Zarr 放到数据根目录。</td></tr>'}</tbody></table></div>`}
views['edge-data']=()=>pHead('实机数据管理','RGB、机械臂状态与 PaXini 触觉统一记录；保留观测与指令的区别。',`<button onclick="pRefreshData()">刷新</button>`)+`<div class="grid2"><section class="card fields"><h2>创建 GELLO 采集片段</h2><p>GELLO 是动作与原始图像的来源；PaXini 取同一工作站上最近的前置有效帧。</p><label for="p-touch-enable"><input id="p-touch-enable" type="checkbox" style="width:auto"> 同步采集 M3025 触觉（231D＋3D 合力）</label><div class="actions"><button class="primary" onclick="pCapture('start')">开始片段</button><button onclick="pCapture('save')">结束并保存</button><button onclick="pCapture('discard')">丢弃片段</button></div><p id="p-capture-status">${pMode==='demo'?(pDemoCapture?'模拟采集中':'模拟采集未开始'):(pStatus.capture?.active?'已记录 '+pStatus.capture.frame_count+' 帧':'未采集')}</p><p class="subtle">仅有效 GELLO 帧才会写入。触觉过期超过 200ms 将拒绝该帧并报告错误；不补零。</p></section><section class="card"><h2>训练数据契约</h2><div class="contract-list"><code>camera_* : uint8 [T,H,W,3]</code><code>robot_joint / action : [T,7]</code><code>tactile : [T,231] · counts</code><code>tactile_resultant : [T,3] · N</code><code>timestamp / source_seq / episode_ends</code></div><p class="subtle">图像原图无损保存。合并多个片段后，按完整 episode 划分训练和验证。</p></section></div><section class="card"><div class="card-head"><h2>数据资产</h2><button onclick="pCombine()">合并所选片段为新数据集</button></div><div id="p-data-table">${pDataTable()}</div></section>`;
async function pRefreshData(){try{await pLoadData();if($('#p-data-table'))$('#p-data-table').innerHTML=pDataTable();toast('已刷新数据列表')}catch(e){toast(e.message)}}
async function pAudit(index){const d=(pMode==='demo'?pDemoRows:pRows)[index];try{const report=pMode==='demo'?d:await pApi('datasets/audit?id='+encodeURIComponent(d.id));modal(`<div class="page-head"><h2>数据完整性检查</h2><button onclick="closeModal()">✕</button></div>${badge(report.valid?'结构有效':'训练前需处理',report.valid?'':'amber')}<pre class="log" style="margin-top:15px;max-height:390px">${esc(JSON.stringify(report,null,2))}</pre><p class="subtle">该检查不自动猜测缺失帧的位置，也不覆盖原始数据。</p>`)}catch(e){toast(e.message)}}
async function pCapture(action){if(pMode==='demo'){if(action==='start'){pDemoCapture={touch:$('#p-touch-enable').checked,start:Date.now()};toast('模拟采集开始')}else if(action==='save'){if(!pDemoCapture)return toast('请先开始模拟片段');pDemoRows.unshift({id:'demo-'+Date.now(),name:'模拟 GELLO 抓放片段',n_steps:Math.max(2,Math.floor((Date.now()-pDemoCapture.start)/100)),n_episodes:1,valid:true,arrays:pDemoCapture.touch?pDemoRows[0].arrays:{action:{shape:[100,7]}},errors:[],warnings:['仅模拟数据']});pDemoCapture=null;toast('模拟片段已保存')}else{pDemoCapture=null;toast('模拟片段已丢弃')}render();return}try{await pApi('capture/'+action,action==='start'?{tactile:$('#p-touch-enable').checked}:{});await pPoll();await pLoadData();render();toast(action==='save'?'实际采集片段已保存':action==='start'?'等待 GELLO 有效帧':'片段已丢弃')}catch(e){toast(e.message)}}
async function pCombine(){const indices=[...document.querySelectorAll('.p-combine:checked')].map(x=>Number(x.value));if(indices.length<2)return toast('至少选择两个片段');if(pMode==='demo')return toast('演示模式：实际合并请在本地工作台执行');try{await pApi('datasets/combine',{datasets:indices.map(i=>pRows[i].id)});await pRefreshData()}catch(e){toast(e.message)}}
function pJobsTable(){const jobs=pMode==='demo'?pJobs:(pStatus.jobs||[]);return `<div class="table-wrap"><table><thead><tr><th>实验</th><th>模态 / 计算位置</th><th>状态</th><th>操作</th></tr></thead><tbody>${jobs.map((j,i)=>`<tr><td><strong>${esc(j.id)}</strong><small>${esc(j.dataset)}</small></td><td>${j.modality==='rgb_tactile'?'RGB＋触觉':'RGB'} / ${esc(j.device||'模拟')}</td><td>${badge(({running:'运行中',completed:'已完成',failed:'失败',cancelled:'已取消'})[j.status]||j.status,j.status==='completed'?'':'blue')}${pMode==='demo'?'<small> 模拟 '+j.progress+'%</small>':''}</td><td><button onclick="pJobDetail(${i})">日志 / 产物</button>${j.status==='running'?` <button onclick="pCancel(${i})">取消</button>`:''}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">还没有 DP 训练任务。</td></tr>'}</tbody></table></div>`}
views['edge-train']=()=>{const rows=pMode==='demo'?pDemoRows:pRows;return pHead('Diffusion Policy 训练中心','从结构有效的数据集训练 7 维关节／夹爪操作策略。',`<button onclick="pRefreshTraining()">刷新数据</button>`)+`<div class="grid2"><section class="card fields"><div class="card-head"><h2>创建 DP 实验</h2>${badge('DIFFUSION POLICY','blue')}</div><label for="p-train-data">数据集（至少两个完整片段）</label><select id="p-train-data">${rows.filter(d=>d.valid&&d.n_episodes>=2).map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</select><label for="p-modality">观测模态</label><select id="p-modality"><option value="rgb">RGB＋关节状态</option><option value="rgb_tactile">RGB＋关节状态＋M3025 触觉</option></select><div class="grid-equal"><div><label for="p-train-device">计算设备</label><select id="p-train-device"><option value="cpu">CPU · 首次验证</option><option value="cuda:0">GPU · cuda:0</option></select></div><div><label for="p-epochs">训练轮数</label><input id="p-epochs" type="number" min="1" max="100000" value="100"></div></div><label for="p-smoke"><input id="p-smoke" type="checkbox" checked style="width:auto"> 首次链路验证：1 次训练步＋验证</label><button class="primary" onclick="pTrain()">${pMode==='demo'?'提交模拟 DP 训练':'启动本地 DP 训练'}</button></section><section class="card"><h2>已集成的训练适配</h2><div class="pipeline-list">${[['7D','动作空间','6 个关节位置目标＋1 个夹爪目标'],['Zarr','直接读取','兼容两路旧格式和三路当前格式'],['RGB+T','触觉融合','231 维分布力＋3 维合力作为低维观测'],['Check','质量门控','帧数、数据块、片段边界与有限值']].map(([a,b,c])=>`<div class="node-row"><span class="node-icon">${a}</span><div><strong>${b}</strong><small>${c}</small></div></div>`).join('')}</div><p class="subtle">实际任务显示子进程状态和日志，不使用模拟进度。模型效果须通过独立实机评测确认。</p></section></div><section class="card"><div class="card-head"><h2>DP 实验记录</h2>${pModeTag()}</div><div id="p-jobs">${pJobsTable()}</div></section>`};
async function pRefreshTraining(){try{await pLoadData();render();toast('训练数据列表已刷新')}catch(e){toast(e.message)}}
async function pTrain(){const dataset=$('#p-train-data').value;if(!dataset)return toast('没有可训练数据，请先检查并合并片段');const body={dataset,modality:$('#p-modality').value,device:$('#p-train-device').value,epochs:Number($('#p-epochs').value),smoke:$('#p-smoke').checked};if(pMode==='demo'){pJobs.unshift({...body,id:'MOCK-DP-'+Date.now().toString().slice(-5),status:'running',progress:0,log:['[MOCK] 仅模拟训练流程，不创建权重。']});render();toast('模拟 DP 实验已创建');return}try{await pApi('training/start',body);await pPoll();render();toast('本地训练进程已启动')}catch(e){toast(e.message)}}
function pJobDetail(index){const j=(pMode==='demo'?pJobs:pStatus.jobs)[index];modal(`<div class="page-head"><h2>${esc(j.id)}</h2><button onclick="closeModal()">✕</button></div><p>${pMode==='demo'?'模拟实验':'本地训练进程'} · ${esc(j.status)}</p><pre class="log" style="max-height:400px">${esc((j.log||[]).join('\n')||'等待进程日志')}</pre><p class="subtle">检查点：${esc(j.checkpoint||(pMode==='demo'?'模拟流程不生成检查点':'尚未生成'))}</p>`)}
async function pCancel(index){const j=(pMode==='demo'?pJobs:pStatus.jobs)[index];if(pMode==='demo'){j.status='cancelled';render();return}try{await pApi('training/cancel',{id:j.id});await pPoll();render()}catch(e){toast(e.message)}}
const originalArchitecture=views.architecture;views.architecture=()=>pHead('端—边—云 · 多模态接入架构','保留 G1 扩展，优先贯通 UR5e、RealSense 与 PaXini 的实机学习链路。',`<a href="architecture-ur5e.svg" download><button>下载新架构图 ↓</button></a>`)+`<div class="arch-container"><img class="arch-img" src="architecture-ur5e.svg" alt="UR5e RealSense PaXini 和 GELLO 经本地服务接入数据与 DP 训练的端边云架构"></div><div class="arch-details"><section class="card"><h3>设备端</h3><p>UR5e / 二指夹爪、RealSense RGB、PaXini M3025 串口。GELLO 负责原有控制。</p></section><section class="card"><h3>边缘服务</h3><p>只读 RTDE、GEN3 UART、图像与动作接入、触觉时间匹配、数据校验及本地训练调度。</p></section><section class="card"><h3>平台与训练</h3><p>同一工作台支持在线演示与本地实机服务。GPU 训练可部署在现场服务器；云端资产同步尚为规划。</p></section></div><p class="subtle">G1 / SONIC / TeleopIt 继续保留为演示与后续适配项目；平台不直接接管机械臂运动。</p>`;
setInterval(()=>{if(pMode==='live'){pPoll();return}let change=false;for(const job of pJobs)if(job.status==='running'){job.progress=Math.min(100,job.progress+10);if(job.progress===100){job.status='completed';job.log.push('[MOCK] 模拟流程完成，无真实模型文件。')}change=true}if(change&&page==='edge-train'&&$('#p-jobs'))$('#p-jobs').innerHTML=pJobsTable()},1500);
if(!location.hash)location.hash='ur5e';render();
